<?php
declare(strict_types=1);
require __DIR__ . '/../app/bootstrap.php';
require __DIR__ . '/../app/Layout.php';

$page=(string)($_GET['page']??'dashboard'); $action=(string)($_POST['action']??'');
if($page==='login'&&!user()){
    if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=db()->prepare('SELECT * FROM users WHERE username=? AND active=1');$s->execute([trim((string)$_POST['username'])]);$u=$s->fetch();if($u&&password_verify((string)$_POST['password'],$u['password_hash'])){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];db()->prepare('UPDATE users SET last_login_at=NOW() WHERE id=?')->execute([$u['id']]);audit('auth.login','user',(int)$u['id']);redirect('index.php');}flash('error','ชื่อผู้ใช้หรือรหัสผ่านไม่ถูกต้อง');}
    render_header('เข้าสู่ระบบ',false); ?>
    <main class="login-wrap"><div class="login-layout"><section class="login-card"><?=brand_logo('login-brand')?><div class="login-heading"><span>SMART OFFICE STOCK</span><h2><?=h(setting('system_name',cfg('app.name')))?></h2><p><?=h(setting('office_name',cfg('app.office_name')))?></p></div><?php render_flashes(); ?><form method="post"><input type="hidden" name="_csrf" value="<?=h(csrf_token())?>"><label>ชื่อผู้ใช้<input name="username" required autofocus autocomplete="username" placeholder="กรอกชื่อผู้ใช้"></label><label>รหัสผ่าน<input type="password" name="password" required autocomplete="current-password" placeholder="กรอกรหัสผ่าน"></label><button class="btn primary"><?=ui_icon('login')?>เข้าสู่ระบบ</button></form><small class="login-help">หากลืมรหัสผ่าน กรุณาติดต่อผู้ดูแลระบบ</small></section></div></main><?php render_footer();exit;
}
if($page==='logout'){if(user())audit('auth.logout','user',(int)user()['id']);session_destroy();redirect('?page=login');}
$u=require_login();

if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();
    try{
        $requests=new RequestService(db());$stock=new StockService(db());
        switch($action){
            case 'request_save': require_role('requester');$id=(int)($_POST['id']??0);$purpose=post_string('purpose',2000);if($id)$requests->updateDraft($id,(int)$u['id'],$purpose,$_POST['material_id']??[],$_POST['quantity']??[]);else$id=$requests->createDraft((int)$u['id'],$u['work_group_id']?:(null),$purpose,$_POST['material_id']??[],$_POST['quantity']??[]);if(isset($_POST['submit'])){$requests->submit($id,(int)$u['id']);flash('success','ส่งคำขอแล้ว');notify_line_for_request($id);}else flash('success','บันทึกแบบร่างแล้ว');redirect('?page=request_view&id='.$id);
            case 'request_submit':require_role('requester');$id=(int)$_POST['id'];$requests->submit($id,(int)$u['id']);flash('success','ส่งคำขอแล้ว');notify_line_for_request($id);break;
            case 'request_cancel':require_role('requester');$requests->cancel((int)$_POST['id'],(int)$u['id'],post_string('reason',1000));flash('success','ยกเลิกคำขอแล้ว');break;
            case 'approve':require_role('approver');$id=(int)$_POST['id'];$decision=(string)$_POST['decision'];$requests->decide($id,$decision,$_POST['approved']??[],trim((string)($_POST['reason']??'')),(int)$u['id']);flash('success','บันทึกผลการอนุมัติแล้ว');notify_line_for_status($id,['approve'=>'approved','return'=>'returned','reject'=>'rejected'][$decision]??'');break;
            case 'notify_ready':require_role('supply');$id=(int)$_POST['id'];$s=db()->prepare("SELECT COUNT(*) FROM requisitions WHERE id=? AND status IN('approved','partially_issued')");$s->execute([$id]);if(!$s->fetchColumn())throw new DomainException('คำขอนี้ไม่อยู่ในสถานะเตรียมจ่าย');$result=notify_line_for_status($id,'ready');if(($result['sent']??0)<1)throw new DomainException('ยังไม่ได้ส่ง LINE: '.($result['message']??'ตรวจสอบการตั้งค่าและ LINE User ID ของผู้เบิก'));flash('success','ส่ง LINE แจ้งผู้เบิกว่าพัสดุพร้อมรับแล้ว');break;
            case 'issue':require_role('supply');$id=(int)$_POST['id'];$issueId=$requests->issue($id,$_POST['issue_qty']??[],post_string('receiver_name',180),post_string('idempotency_key',100),trim((string)($_POST['note']??'')),(int)$u['id']);flash('success','ยืนยันจ่ายวัสดุและตัดสต๊อกแล้ว');notify_line_for_status($id,'issued',$issueId);break;
            case 'close_request':require_role('supply');$requests->close((int)$_POST['id'],post_string('reason',1000),(int)$u['id']);flash('success','ปิดยอดค้างแล้ว');break;
            case 'confirm_receipt':require_role('requester');$requests->confirmReceipt((int)$_POST['issue_id'],(int)$u['id']);flash('success','ยืนยันรับของแล้ว คำขอจะเสร็จสมบูรณ์เมื่อยืนยันครบทุกใบจ่าย');break;
            case 'receive_stock':require_role('supply');$date=post_string('received_date',10);$parsed=DateTimeImmutable::createFromFormat('!Y-m-d',$date);if(!$parsed||$parsed->format('Y-m-d')!==$date)throw new DomainException('วันที่รับเข้าไม่ถูกต้อง');$stock->receive((int)$_POST['material_id'],ensure_positive($_POST['quantity']),$date,post_string('source',200),trim((string)($_POST['reference_no']??'')),(int)$u['id'],isset($_POST['opening']));flash('success','บันทึกรับเข้าและปรับยอดแล้ว');break;
            case 'return_stock':require_role('supply');$stock->returnItem((int)$_POST['issue_item_id'],max(0,(float)$_POST['good_qty']),max(0,(float)$_POST['damaged_qty']),post_string('returned_by_name',180),post_string('reason',1000),(int)$u['id']);flash('success','บันทึกคืนวัสดุแล้ว');break;
            case 'count_create':require_role('supply');$id=$stock->createCount($_POST['material_ids']??[],(int)$u['id'],trim((string)($_POST['note']??'')));flash('success','สร้างรอบตรวจนับแล้ว');redirect('?page=count_view&id='.$id);
            case 'count_confirm':require_role('supply');$stock->confirmCount((int)$_POST['id'],$_POST['actual']??[],$_POST['reason']??[],(int)$u['id']);flash('success','ยืนยันผลตรวจนับและปรับยอดแล้ว');break;
            case 'movement_reverse':require_role('supply');$stock->reverseMovement((int)$_POST['id'],post_string('reason',1000),(int)$u['id']);flash('success','สร้างรายการกลับรายการแล้ว');break;
            case 'material_save':require_role('supply','admin');save_material();flash('success','บันทึกทะเบียนวัสดุแล้ว');break;
            case 'material_import':require_role('supply','admin');if(!isset($_FILES['csv'])||$_FILES['csv']['error']!==UPLOAD_ERR_OK)throw new DomainException('กรุณาเลือกไฟล์ CSV ที่อัปโหลดสำเร็จ');$file=$_FILES['csv'];if($file['size']>2*1024*1024)throw new DomainException('ไฟล์ CSV ต้องไม่เกิน 2 MB');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);if(!in_array($mime,['text/plain','text/csv','application/csv','application/vnd.ms-excel','application/octet-stream'],true))throw new DomainException('ชนิดไฟล์ไม่ถูกต้อง กรุณาใช้ CSV UTF-8');$result=(new MaterialImportService(db()))->import($file['tmp_name'],(int)$u['id']);flash('success','นำเข้าสำเร็จ: เพิ่มใหม่ '.$result['created'].' รายการ, ปรับปรุง '.$result['updated'].' รายการ');break;
            case 'user_save':require_role('admin');save_user();flash('success','บันทึกบัญชีและสิทธิ์แล้ว');break;
            case 'group_save':require_role('admin');db()->prepare('INSERT INTO work_groups(name) VALUES(?)')->execute([post_string('name',150)]);audit('group.create','work_group',(int)db()->lastInsertId());flash('success','เพิ่มกลุ่มงานแล้ว');break;
            case 'settings_save':require_role('admin');save_settings((int)$u['id']);flash('success','บันทึกชื่อ โลโก้ และรูปแบบหน้าจอแล้ว');break;
            case 'navigation_report_settings_save':require_role('admin');save_navigation_report_settings((int)$u['id']);flash('success','บันทึกการตั้งค่าเมนูและรายงานแล้ว');break;
            case 'requisition_print_settings_save':require_role('admin');save_requisition_print_settings((int)$u['id']);flash('success','บันทึกรูปแบบใบเบิกวัสดุแล้ว');break;
            case 'line_settings_save':require_role('admin');save_line_settings((int)$u['id']);flash('success','บันทึกการแจ้งเตือน LINE แล้ว');break;
            case 'line_test_notification':require_role('admin');$result=(new LineNotificationService(db()))->sendTest($u['full_name']);if($result['failed']||$result['sent']<1)throw new DomainException('ส่งข้อความทดสอบไม่สำเร็จ: '.$result['message']);audit('notification.line_test','settings',null,null,['sent'=>$result['sent']]);flash('success','ส่งข้อความทดสอบไปยัง LINE สำเร็จ '.$result['sent'].' บัญชี');break;
            default: throw new DomainException('ไม่รู้จักคำสั่ง');
        }
    }catch(Throwable$e){flash('error',$e instanceof DomainException||cfg('app.debug',false)?$e->getMessage():'เกิดข้อผิดพลาด กรุณาลองใหม่');}
    redirect($_SERVER['HTTP_REFERER']??'index.php');
}

require __DIR__ . '/../app/views.php';

function save_material(): void {
    $id=(int)($_POST['id']??0);$code=post_string('code',50);$name=post_string('name',200);$unit=post_string('unit',50);$min=max(0,(float)($_POST['minimum_qty']??0));$data=[$code,$name,(int)$_POST['category_id']?:null,trim((string)($_POST['description']??'')),$unit,$min,trim((string)($_POST['location']??'')),isset($_POST['active'])?1:0,isset($_POST['track_assignee'])?1:0];
    if($id){$old=db()->prepare('SELECT * FROM materials WHERE id=?');$old->execute([$id]);$before=$old->fetch();if(!$before)throw new DomainException('ไม่พบวัสดุ');db()->prepare('UPDATE materials SET code=?,name=?,category_id=?,description=?,unit=?,minimum_qty=?,location=?,active=?,track_assignee=? WHERE id=?')->execute([...$data,$id]);audit('material.update','material',$id,$before,$data);}else{db()->prepare('INSERT INTO materials(code,name,category_id,description,unit,minimum_qty,location,active,track_assignee) VALUES(?,?,?,?,?,?,?,?,?)')->execute($data);$id=(int)db()->lastInsertId();audit('material.create','material',$id,null,$data);}
    if(isset($_FILES['image'])&&$_FILES['image']['error']!==UPLOAD_ERR_NO_FILE){$f=$_FILES['image'];if($f['error']!==UPLOAD_ERR_OK||$f['size']>(int)cfg('upload.max_bytes'))throw new DomainException('รูปภาพอัปโหลดไม่สำเร็จหรือมีขนาดเกินกำหนด');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);if(!in_array($mime,['image/jpeg','image/png','image/webp'],true))throw new DomainException('อนุญาตเฉพาะรูป JPEG, PNG หรือ WebP');$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime];$name=bin2hex(random_bytes(20)).'.'.$ext;$dir=(string)cfg('upload.directory');if(!is_dir($dir)&&!mkdir($dir,0750,true))throw new RuntimeException('สร้างพื้นที่เก็บไฟล์ไม่ได้');if(!move_uploaded_file($f['tmp_name'],$dir.DIRECTORY_SEPARATOR.$name))throw new RuntimeException('จัดเก็บรูปภาพไม่ได้');db()->prepare('UPDATE materials SET image_path=? WHERE id=?')->execute([$name,$id]);}
}
function save_settings(int$actor):void{
    $values=['system_name'=>post_string('system_name',120),'office_name'=>post_string('office_name',200),'request_prefix'=>post_string('request_prefix',20)];
    $theme=(string)($_POST['theme_color']??'blue');if(!in_array($theme,['blue','navy','teal','green','purple'],true))throw new DomainException('โทนสีไม่ถูกต้อง');$values['theme_color']=$theme;
    $values['logo_path']=isset($_POST['remove_logo'])?'':(string)setting('logo_path','');$newFile=null;
    if(isset($_FILES['logo'])&&$_FILES['logo']['error']!==UPLOAD_ERR_NO_FILE){$f=$_FILES['logo'];if($f['error']!==UPLOAD_ERR_OK||$f['size']<=0||$f['size']>(int)cfg('upload.max_bytes'))throw new DomainException('โลโก้อัปโหลดไม่สำเร็จหรือมีขนาดเกิน 2 MB');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);if(!in_array($mime,['image/jpeg','image/png','image/webp'],true))throw new DomainException('โลโก้อนุญาตเฉพาะ JPEG, PNG หรือ WebP');$size=@getimagesize($f['tmp_name']);if(!$size||$size[0]>4000||$size[1]>4000)throw new DomainException('ไฟล์โลโก้ไม่ใช่รูปภาพที่ถูกต้องหรือมีขนาดเกิน 4,000 พิกเซล');$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime];$newFile=bin2hex(random_bytes(20)).'.'.$ext;$dir=dirname((string)cfg('upload.directory')).DIRECTORY_SEPARATOR.'branding';if(!is_dir($dir)&&!mkdir($dir,0750,true))throw new RuntimeException('สร้างพื้นที่เก็บโลโก้ไม่ได้');if(!move_uploaded_file($f['tmp_name'],$dir.DIRECTORY_SEPARATOR.$newFile))throw new RuntimeException('จัดเก็บโลโก้ไม่ได้');$values['logo_path']=$newFile;}
    $before=[];foreach(array_keys($values)as$key)$before[$key]=setting($key,'');db()->beginTransaction();try{$s=db()->prepare('INSERT INTO settings(setting_key,setting_value,updated_by) VALUES(?,?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_by=VALUES(updated_by)');foreach($values as$key=>$value)$s->execute([$key,$value,$actor]);audit('settings.update','settings',null,$before,$values);db()->commit();}catch(Throwable$e){db()->rollBack();if($newFile){$path=dirname((string)cfg('upload.directory')).DIRECTORY_SEPARATOR.'branding'.DIRECTORY_SEPARATOR.$newFile;if(is_file($path))unlink($path);}throw$e;}
}
function save_navigation_report_settings(int$actor):void{
    $orientation=(string)($_POST['report_orientation']??'landscape');if(!in_array($orientation,['portrait','landscape'],true))throw new DomainException('แนวกระดาษไม่ถูกต้อง');
    $optional=function(string$key,int$max):string{$value=trim((string)($_POST[$key]??''));if(mb_strlen($value)>$max)throw new DomainException($key.' ยาวเกินกำหนด');return$value;};
    $values=['report_header_text'=>$optional('report_header_text',200),'report_footer_text'=>$optional('report_footer_text',300),'report_prepared_label'=>post_string('report_prepared_label',80),'report_checked_label'=>post_string('report_checked_label',80),'report_orientation'=>$orientation,'report_show_logo'=>isset($_POST['report_show_logo'])?'1':'0'];
    $labels=is_array($_POST['menu_label']??null)?$_POST['menu_label']:[];$orders=is_array($_POST['menu_order']??null)?$_POST['menu_order']:[];$enabled=is_array($_POST['menu_enabled']??null)?$_POST['menu_enabled']:[];
    foreach(menu_catalog()as$page=>$item){$label=trim((string)($labels[$page]??$item['label']));if($label===''||mb_strlen($label)>60)throw new DomainException('ชื่อเมนูต้องมี 1-60 ตัวอักษร');$order=max(1,min(999,(int)($orders[$page]??$item['order'])));$values['menu_label_'.$page]=$label;$values['menu_order_'.$page]=(string)$order;$values['menu_enabled_'.$page]=in_array($page,['dashboard','admin_navigation_reports'],true)||isset($enabled[$page])?'1':'0';}
    $before=[];foreach(array_keys($values)as$key)$before[$key]=setting($key,'');db()->beginTransaction();try{$s=db()->prepare('INSERT INTO settings(setting_key,setting_value,updated_by) VALUES(?,?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_by=VALUES(updated_by)');foreach($values as$key=>$value)$s->execute([$key,$value,$actor]);audit('settings.navigation_report_update','settings',null,$before,$values);db()->commit();}catch(Throwable$e){db()->rollBack();throw$e;}
}
function save_requisition_print_settings(int$actor):void{
    $required=['requisition_print_title'=>120,'requisition_print_request_no_label'=>60,'requisition_print_date_label'=>60,'requisition_print_requester_label'=>60,'requisition_print_group_label'=>60,'requisition_print_purpose_label'=>60,'requisition_print_item_label'=>60,'requisition_print_requested_label'=>60,'requisition_print_approved_label'=>60,'requisition_print_issued_label'=>60,'requisition_print_sign_requester'=>80,'requisition_print_sign_approver'=>80,'requisition_print_sign_issuer'=>80,'requisition_print_sign_receiver'=>80];$optional=['requisition_print_subtitle'=>200,'requisition_print_header_text'=>500,'requisition_print_footer_text'=>500];$values=[];
    foreach($required as$key=>$max)$values[$key]=post_string($key,$max);foreach($optional as$key=>$max){$value=trim((string)($_POST[$key]??''));if(mb_strlen($value)>$max)throw new DomainException($key.' ยาวเกินกำหนด');$values[$key]=$value;}$values['requisition_print_show_logo']=isset($_POST['requisition_print_show_logo'])?'1':'0';$values['requisition_print_show_status']=isset($_POST['requisition_print_show_status'])?'1':'0';
    $before=[];foreach(array_keys($values)as$key)$before[$key]=setting($key,'');db()->beginTransaction();try{$s=db()->prepare('INSERT INTO settings(setting_key,setting_value,updated_by) VALUES(?,?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_by=VALUES(updated_by)');foreach($values as$key=>$value)$s->execute([$key,$value,$actor]);audit('settings.requisition_print_update','settings',null,$before,$values);db()->commit();}catch(Throwable$e){db()->rollBack();throw$e;}
}
function save_line_settings(int$actor):void{
    $enabled=isset($_POST['enabled']);$reminderEnabled=isset($_POST['reminder_enabled']);$recipients=LineNotificationService::parseRecipients((string)($_POST['recipient_user_ids']??''));
    if($enabled&&!$recipients)throw new DomainException('กรุณากำหนด LINE User ID ผู้รับอย่างน้อยหนึ่งบัญชีก่อนเปิดใช้งาน');
    if($enabled&&trim((string)cfg('line.channel_access_token',''))==='')throw new DomainException('กรุณาตั้งค่า LINE_CHANNEL_ACCESS_TOKEN ใน config หรือ environment ก่อนเปิดใช้งาน');
    if($reminderEnabled&&!$enabled)throw new DomainException('กรุณาเปิดการแจ้งเตือน LINE ก่อนเปิดแจ้งเตือนงานค้าง');$days=[];foreach(['reminder_pending_days','reminder_issue_days','reminder_receipt_days']as$key){$value=filter_var($_POST[$key]??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1,'max_range'=>90]]);if($value===false)throw new DomainException('จำนวนวันแจ้งเตือนต้องอยู่ระหว่าง 1 ถึง 90 วัน');$days[$key]=(string)$value;}
    $values=['line_notifications_enabled'=>$enabled?'1':'0','line_recipient_user_ids'=>implode("\n",$recipients),'reminder_notifications_enabled'=>$reminderEnabled?'1':'0',...$days];
    $before=[];foreach(array_keys($values)as$key)$before[$key]=setting($key,'');$before['recipient_count']=count(LineNotificationService::parseRecipients((string)setting('line_recipient_user_ids','')));
    db()->beginTransaction();try{$s=db()->prepare('INSERT INTO settings(setting_key,setting_value,updated_by) VALUES(?,?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_by=VALUES(updated_by)');foreach($values as$key=>$value)$s->execute([$key,$value,$actor]);audit('settings.line_notification_update','settings',null,$before,['line_notifications_enabled'=>$values['line_notifications_enabled'],'reminder_notifications_enabled'=>$values['reminder_notifications_enabled'],'reminder_pending_days'=>$values['reminder_pending_days'],'reminder_issue_days'=>$values['reminder_issue_days'],'reminder_receipt_days'=>$values['reminder_receipt_days'],'recipient_count'=>count($recipients)]);db()->commit();}catch(Throwable$e){db()->rollBack();throw$e;}
}
function notify_line_for_request(int$id):void{
    try{$result=(new LineNotificationService(db()))->notifyRequisitionSubmitted($id);if($result['enabled']&&($result['failed']>0||($result['sent']===0&&$result['skipped']>0)))flash('warning','คำขอถูกบันทึกแล้ว แต่การแจ้งเตือน LINE มีปัญหา: '.$result['message']);}
    catch(Throwable$e){flash('warning','คำขอถูกบันทึกแล้ว แต่ระบบไม่สามารถส่งแจ้งเตือน LINE ได้ กรุณาแจ้งเจ้าหน้าที่พัสดุโดยตรง');}
}
function notify_line_for_status(int$id,string$event,?int$issueId=null):array{
    if($event==='')return[];try{$result=(new LineNotificationService(db()))->notifyRequesterStatus($id,$event,$issueId);if($result['failed']>0)flash('warning','บันทึกรายการแล้ว แต่ส่ง LINE ถึงผู้เบิกไม่สำเร็จ: '.$result['message']);return$result;}
    catch(Throwable$e){flash('warning','บันทึกรายการแล้ว แต่ระบบไม่สามารถส่ง LINE ถึงผู้เบิกได้');return['sent'=>0,'failed'=>1,'skipped'=>0,'message'=>'เกิดข้อผิดพลาดขณะส่ง'];}
}
function save_user(): void {
    $id=(int)($_POST['id']??0);$name=post_string('full_name',180);$username=post_string('username',80);$active=isset($_POST['active'])?1:0;$group=(int)($_POST['work_group_id']??0)?:null;$password=(string)($_POST['password']??'');$lineUserId=LineNotificationService::validateUserId((string)($_POST['line_user_id']??''))?:null;
    $roles=array_values(array_intersect(['requester','approver','supply','admin'],$_POST['roles']??[]));if(!$roles)throw new DomainException('บัญชีต้องมีอย่างน้อยหนึ่งบทบาท');
    if($id===(int)user()['id']&&(!$active||!in_array('admin',$roles,true)))throw new DomainException('ไม่สามารถปิดบัญชีหรือนำสิทธิ์ผู้ดูแลออกจากบัญชีที่กำลังใช้งาน');
    db()->beginTransaction();try{if($id){$s=db()->prepare('SELECT * FROM users WHERE id=? FOR UPDATE');$s->execute([$id]);$old=$s->fetch();if(!$old)throw new DomainException('ไม่พบบัญชี');$s=db()->prepare("SELECT COUNT(*) FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=? AND r.code='admin'");$s->execute([$id]);$wasAdmin=(bool)$s->fetchColumn();if($wasAdmin&&(!$active||!in_array('admin',$roles,true))){$admins=(int)db()->query("SELECT COUNT(DISTINCT u.id) FROM users u JOIN user_roles ur ON ur.user_id=u.id JOIN roles r ON r.id=ur.role_id WHERE u.active=1 AND r.code='admin'")->fetchColumn();if($admins<=1)throw new DomainException('ต้องมีผู้ดูแลระบบที่เปิดใช้งานอย่างน้อยหนึ่งบัญชี');}db()->prepare('UPDATE users SET username=?,full_name=?,line_user_id=?,work_group_id=?,active=? WHERE id=?')->execute([$username,$name,$lineUserId,$group,$active,$id]);if($password!==''){if(!password_meets_minimum($password))throw new DomainException('รหัสผ่านต้องยาวอย่างน้อย 6 ตัวอักษร');db()->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($password,PASSWORD_DEFAULT),$id]);}}else{if(!password_meets_minimum($password))throw new DomainException('รหัสผ่านต้องยาวอย่างน้อย 6 ตัวอักษร');db()->prepare('INSERT INTO users(username,password_hash,full_name,line_user_id,work_group_id,active) VALUES(?,?,?,?,?,?)')->execute([$username,password_hash($password,PASSWORD_DEFAULT),$name,$lineUserId,$group,$active]);$id=(int)db()->lastInsertId();$old=null;}db()->prepare('DELETE FROM user_roles WHERE user_id=?')->execute([$id]);$s=db()->prepare('INSERT INTO user_roles(user_id,role_id) SELECT ?,id FROM roles WHERE code=?');foreach($roles as$r)$s->execute([$id,$r]);audit('user.roles_update','user',$id,$old,['roles'=>$roles,'active'=>$active,'line_connected'=>$lineUserId!==null]);db()->commit();}catch(Throwable$e){db()->rollBack();throw$e;}
}
